create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade,display_name text not null default 'User',created_at timestamptz not null default now());
create table if not exists public.messages (id bigint generated by default as identity primary key,sender_id uuid not null references public.profiles(id) on delete cascade,receiver_id uuid not null references public.profiles(id) on delete cascade,content text not null default '',message_type text not null default 'text' check (message_type in ('text','file','voice')),file_url text,file_name text,file_type text,file_size bigint,created_at timestamptz not null default now(),read_at timestamptz);
create index if not exists messages_sender_receiver_idx on public.messages(sender_id,receiver_id,created_at);
create index if not exists messages_receiver_sender_idx on public.messages(receiver_id,sender_id,created_at);
alter table public.profiles enable row level security;alter table public.messages enable row level security;
drop policy if exists "profiles_select_authenticated" on public.profiles;create policy "profiles_select_authenticated" on public.profiles for select to authenticated using (true);
drop policy if exists "profiles_insert_own" on public.profiles;create policy "profiles_insert_own" on public.profiles for insert to authenticated with check (auth.uid()=id);
drop policy if exists "profiles_update_own" on public.profiles;create policy "profiles_update_own" on public.profiles for update to authenticated using (auth.uid()=id) with check (auth.uid()=id);
drop policy if exists "messages_select_participants" on public.messages;create policy "messages_select_participants" on public.messages for select to authenticated using (auth.uid()=sender_id or auth.uid()=receiver_id);
drop policy if exists "messages_insert_sender" on public.messages;create policy "messages_insert_sender" on public.messages for insert to authenticated with check (auth.uid()=sender_id);
drop policy if exists "messages_update_recipient" on public.messages;create policy "messages_update_recipient" on public.messages for update to authenticated using (auth.uid()=receiver_id) with check (auth.uid()=receiver_id);
alter table public.messages replica identity full;
alter publication supabase_realtime add table public.messages;
